#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

require_file() {
  local path="$1"
  if [[ ! -f "$path" ]]; then
    echo "missing file: $path" >&2
    exit 1
  fi
}

require_text() {
  local path="$1"
  local text="$2"
  if ! rg -q --fixed-strings "$text" "$path"; then
    echo "missing text in $path: $text" >&2
    exit 1
  fi
}

forbidden_text() {
  local path="$1"
  local text="$2"
  if rg -q --fixed-strings "$text" "$path"; then
    echo "forbidden text in $path: $text" >&2
    exit 1
  fi
}

